import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.CB_NIqHd.js";const h=JSON.parse('{"title":"What does quality gate mean for you – an ideal set up of quality gates?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Clean_code_and_Code_Quality/What_does_quality_gate_mean_for_you_–_an_ideal_set_up_of_quality_gates.md","filePath":"senior_growth/Clean_code_and_Code_Quality/What_does_quality_gate_mean_for_you_–_an_ideal_set_up_of_quality_gates.md"}'),n={name:"senior_growth/Clean_code_and_Code_Quality/What_does_quality_gate_mean_for_you_–_an_ideal_set_up_of_quality_gates.md"};function o(s,e,l,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="what-does-quality-gate-mean-for-you-–-an-ideal-set-up-of-quality-gates" tabindex="-1">What does quality gate mean for you – an ideal set up of quality gates? <a class="header-anchor" href="#what-does-quality-gate-mean-for-you-–-an-ideal-set-up-of-quality-gates" aria-label="Permalink to “What does quality gate mean for you – an ideal set up of quality gates?”">​</a></h1><h2 id="🏁-quality-gate-in-software-development" tabindex="-1">🏁 Quality Gate in Software Development <a class="header-anchor" href="#🏁-quality-gate-in-software-development" aria-label="Permalink to “🏁 Quality Gate in Software Development”">​</a></h2><p>A <strong>quality gate</strong> is a set of <strong>automated checks</strong> that code must pass before it can be merged or deployed. It enforces the configured checks and limits; passing them does not prove overall safety, completeness or correct requirements.</p><hr><h2 id="_1️⃣-what-a-quality-gate-means" tabindex="-1">1️⃣ What a Quality Gate Means <a class="header-anchor" href="#_1️⃣-what-a-quality-gate-means" aria-label="Permalink to “1️⃣ What a Quality Gate Means”">​</a></h2><ul><li><strong>Automated enforcement</strong> of coding standards, tests, and metrics.</li><li>Acts as a <strong>“stoplight”</strong>: code either <strong>passes (green)</strong> or <strong>fails (red)</strong> based on criteria.</li><li>Usually implemented in <strong>CI/CD pipelines</strong> using tools like <strong>SonarQube, ESLint, Stylelint, Prettier, Jest coverage, Cypress tests</strong>, etc.</li></ul><hr><h2 id="_2️⃣-ideal-set-up-for-a-quality-gate" tabindex="-1">2️⃣ Ideal Set Up for a Quality Gate <a class="header-anchor" href="#_2️⃣-ideal-set-up-for-a-quality-gate" aria-label="Permalink to “2️⃣ Ideal Set Up for a Quality Gate”">​</a></h2><h3 id="✅-code-quality-metrics" tabindex="-1">✅ Code Quality Metrics <a class="header-anchor" href="#✅-code-quality-metrics" aria-label="Permalink to “✅ Code Quality Metrics”">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Illustrative policy — justify for the project</th></tr></thead><tbody><tr><td><strong>Code coverage</strong></td><td>≥ 80% unit &amp; integration coverage</td></tr><tr><td><strong>Test pass rate</strong></td><td>100% passing</td></tr><tr><td><strong>Static code analysis</strong></td><td>No critical or blocker issues; low warning count</td></tr><tr><td><strong>Code duplication</strong></td><td>&lt; 5% duplicated code</td></tr><tr><td><strong>Cyclomatic complexity</strong></td><td>Reasonable limits per function/module (e.g., &lt; 10)</td></tr><tr><td><strong>Linting &amp; formatting</strong></td><td>No linting errors; consistent code style</td></tr></tbody></table><h3 id="✅-security-vulnerability-checks" tabindex="-1">✅ Security &amp; Vulnerability Checks <a class="header-anchor" href="#✅-security-vulnerability-checks" aria-label="Permalink to “✅ Security &amp; Vulnerability Checks”">​</a></h3><ul><li>No <strong>high/critical security vulnerabilities</strong> in dependencies.</li><li>Enforce <strong>OWASP best practices</strong> (XSS, injection prevention, etc.).</li><li>Check <strong>secret keys or tokens</strong> are not exposed.</li></ul><h3 id="✅-build-deployment-checks" tabindex="-1">✅ Build &amp; Deployment Checks <a class="header-anchor" href="#✅-build-deployment-checks" aria-label="Permalink to “✅ Build &amp; Deployment Checks”">​</a></h3><ul><li>Successful <strong>build pipeline</strong>.</li><li>All <strong>unit, integration, and E2E tests pass</strong>.</li><li>Optional: <strong>Performance tests</strong> (e.g., bundle size, load times).</li></ul><h3 id="✅-documentation-best-practices" tabindex="-1">✅ Documentation &amp; Best Practices <a class="header-anchor" href="#✅-documentation-best-practices" aria-label="Permalink to “✅ Documentation &amp; Best Practices”">​</a></h3><ul><li>PRs include <strong>description, testing instructions, and changelog</strong>.</li><li>Code is <strong>readable, modular, and follows design patterns</strong>.</li><li><strong>Commit messages</strong> follow team conventions.</li></ul><hr><h2 id="_3️⃣-how-it-works-in-ci-cd" tabindex="-1">3️⃣ How It Works in CI/CD <a class="header-anchor" href="#_3️⃣-how-it-works-in-ci-cd" aria-label="Permalink to “3️⃣ How It Works in CI/CD”">​</a></h2><ol><li>Developer pushes a branch → CI pipeline triggers.</li><li>Quality gate runs: <ul><li>Linting &amp; formatting</li><li>Static code analysis</li><li>Unit &amp; integration tests</li><li>Security checks</li><li>Coverage thresholds</li></ul></li><li>Pipeline fails if <strong>any criteria are not met</strong> → PR cannot be merged.</li><li>Once all configured criteria pass → review required evidence and repository policy; untested behavior and incorrect requirements remain risks.</li></ol><hr><h2 id="_4️⃣-benefits-of-a-quality-gate" tabindex="-1">4️⃣ Benefits of a Quality Gate <a class="header-anchor" href="#_4️⃣-benefits-of-a-quality-gate" aria-label="Permalink to “4️⃣ Benefits of a Quality Gate”">​</a></h2><ul><li><strong>Blocks detected violations</strong> before production.</li><li><strong>Encourages best practices</strong> across the team.</li><li><strong>Early detection of issues</strong> reduces technical debt.</li><li><strong>Confidence in CI/CD deployments</strong>.</li><li>Supports <strong>continuous improvement</strong> with measurable metrics.</li></ul><hr><h3 id="✅-key-takeaways" tabindex="-1">✅ Key Takeaways <a class="header-anchor" href="#✅-key-takeaways" aria-label="Permalink to “✅ Key Takeaways”">​</a></h3><ul><li>Quality gates are <strong>automated checkpoints</strong> for code quality, testing, and security.</li><li>A project-specific setup might enforce: <ul><li>≥80% coverage, all tests passing</li><li>No critical/static analysis issues</li><li>Linting, formatting, and modular code</li><li>Security and dependency checks</li><li>Optional performance benchmarks</li></ul></li><li>Quality gates <strong>save time, reduce bugs, and enforce maintainable, reliable software</strong>.</li></ul><blockquote><p>💡 Senior Tip:<br> Required gates need clear ownership and an audited exceptional-change policy; silently bypassing a failing check defeats its purpose.</p></blockquote><h2 id="a-runnable-gate-with-explicit-limits" tabindex="-1">A runnable gate with explicit limits <a class="header-anchor" href="#a-runnable-gate-with-explicit-limits" aria-label="Permalink to “A runnable gate with explicit limits”">​</a></h2><p>Use the <a href="./What_is_code_standard_What_code_standard_is_on_your_current_project_Should_we_always_work_by_code_standard_Have_you_used_linters_and_do_you_have_any_experience_in_configuring_them.html#minimal-executable-standard">complete minimal standard fixture</a>: npm run check executes lint, strict JavaScript typechecking, behavior tests and emit in sequence. Run it in a fresh locked practice checkout for CI parity. Hooks can be bypassed; configure the CI job/status as required in the actual repository. This document supplies executable local commands, not a claim that a hosted workflow or branch protection is installed.</p><p>Coverage≥80%, duplication&lt;5% and complexity&lt;10 above are examples, not universal ideals. Coverage shows execution, not assertions or correct requirements; test a meaningful boundary rather than manufacture coverage. Pin measurement tool/version, scope/generated exclusions and regression policy. A dependency audit finding requires triage of affected paths and a tracked remediation/exception; no findings does not establish no vulnerabilities. Security controls and critical behavior need their own threat/acceptance evidence.</p><p><strong>Exercise:</strong> retain baseline success and lint/type/test failure exits from the shared lab. Add a failing required scenario that is absent from the initial test and observe why the original green gate missed it. Document one justified coverage/complexity policy with owner, cost, false positives and review trigger. Acceptance: distinguish local commands, real hosted execution and repository merge policy; never report an unrun CI deployment or a green gate as professional readiness. Learner CI configuration and project-specific risk review remain required.</p>',30)])])}const p=t(n,[["render",o]]);export{h as __pageData,p as default};
